        {
          "tool_name": "x-article__x_home_timeline",
          "description": "Read the home timeline (Following or For You). Returns a compact tweet list (tweetId, text, screenName, url, likedByMe, following, followedBy, followRequestSent, badgeType, followersCount) plus nextCursor for pagination. Does not include promoted posts. count is timeline slots, not flattened replies. likedByMe / following are boolean or null when X omitted the field — do not probe with x_like / x_follow.",
          "score": 4.837660789489746,
          "input_schema": {
            "type": "object",
            "properties": {
              "account": {
                "type": "string",
                "enum": [
                  "クオ",
                  "ベル"
                ],
                "description": "X account. Required. No default. Registered now: クオ, ベル. Use one of these names. If empty, call x_article_set_credentials or x_account_adopt first."
              },
              "tab": {
                "type": "string",
                "enum": [
                  "following",
                  "foryou"
                ],
                "description": "following = HomeLatestTimeline (default). foryou = HomeTimeline (ranked)."
              },
              "count": {
                "type": "integer",
                "minimum": 1,
                "maximum": 40,
                "description": "Requested X page size, 1–40. Default 20. X may return more entries in a page."
